package com.simplemdm.service.mdm;
import com.simplemdm.exception.BusinessException;import com.simplemdm.model.mdm.*;import com.simplemdm.model.system.User;import com.simplemdm.model.workflow.*;import com.simplemdm.repository.mdm.*;import com.simplemdm.repository.system.UserRepository;import com.simplemdm.repository.workflow.*;import com.simplemdm.service.system.AuthorizationService;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;
@Component class RecordServiceApprovedWriter implements ApprovedRecordWriter {
 private final RecordService service;private final CurrentUserProvider current;private final ApproverAssignmentRepository assignments;private final AuthorizationService authorization;private final MdmRecordRepository records;private final ApprovalRequestRepository requests;private final ApprovalChangeRepository changes;private final ApprovalActionRepository actions;private final FieldDefinitionRepository fields;private final UserRepository users;
 RecordServiceApprovedWriter(RecordService service,CurrentUserProvider current,ApproverAssignmentRepository assignments,AuthorizationService authorization,MdmRecordRepository records,ApprovalRequestRepository requests,ApprovalChangeRepository changes,ApprovalActionRepository actions,FieldDefinitionRepository fields,UserRepository users){this.service=service;this.current=current;this.assignments=assignments;this.authorization=authorization;this.records=records;this.requests=requests;this.changes=changes;this.actions=actions;this.fields=fields;this.users=users;}
 @Transactional public RecordView apply(Long requestId){if(requestId==null)throw new BusinessException(400,"Approval request ID is required");ApprovalRequest request=requests.findById(requestId).orElseThrow(()->new BusinessException(404,"Approval request not found"));if(!"PENDING".equals(request.getStatus()))throw new BusinessException(409,"Approval request is not pending");Long actor=current.currentSystemUserId().orElseThrow(()->new BusinessException(401,"No authenticated system user"));User user=users.findById(actor).orElseThrow(()->new BusinessException(401,"Authenticated user not found"));if(!user.isActive()||!user.getSystemId().equals(request.getSystemId()))throw new BusinessException(403,"Approval actor is invalid");MdmRecord record=records.findBySystemIdAndId(request.getSystemId(),request.getRecordId()).orElseThrow(()->new BusinessException(404,"Record not found"));if(!record.getObjectTypeId().equals(request.getObjectTypeId())||!record.getDepartmentId().equals(request.getDepartmentId()))throw new BusinessException(409,"Approval target mismatch");if(record.getVersion()!=request.getExpectedVersion())throw new BusinessException(409,"Record version conflict");if(!assignments.existsActiveAssignment(request.getSystemId(),request.getObjectTypeId(),request.getDepartmentId(),actor)||!authorization.can(actor,"APPROVAL_REVIEW",request.getDepartmentId()))throw new BusinessException(403,"Approval capability denied");Map<Long,FieldDefinition> definitions=fields.findByObjectTypeId(request.getObjectTypeId()).stream().collect(Collectors.toMap(FieldDefinition::getId,Function.identity()));Map<String,Object> data=new LinkedHashMap<>();for(ApprovalChange change:changes.findByApprovalRequestId(requestId)){FieldDefinition field=definitions.get(change.getFieldDefinitionId());if(field==null)throw new BusinessException(409,"Approval field no longer exists");data.put(field.getFieldKey(),apiValue(field,change.newValue()));}if(data.isEmpty())throw new BusinessException(409,"Approval contains no changes");RecordView result=service.applyApprovedUpdate(actor,record.getId(),request.getExpectedVersion(),data);request.approve();requests.saveAndFlush(request);actions.save(ApprovalAction.approved(request.getSystemId(),requestId,actor));return result;}
 private Object apiValue(FieldDefinition f,TypedValue v){if(f.getDataType()==FieldDataType.REFERENCE)return v.referenceRecordId()==null?null:new TypedValueConverter.ReferenceValue(v.referenceRecordId(),f.getReferenceObjectTypeId(),f.getSystemId());if(v.stringValue()!=null)return v.stringValue();if(v.textValue()!=null)return v.textValue();if(v.integerValue()!=null)return v.integerValue();if(v.decimalValue()!=null)return v.decimalValue();if(v.booleanValue()!=null)return v.booleanValue();if(v.dateValue()!=null)return v.dateValue();return v.datetimeValue();}
}
